<?php require __DIR__.'/includes/bootstrap.php';requireRole('admin');if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit('Method not allowed.');}$id=(int)($_POST['event_id']??0);$action=$_POST['action']??'';$map=['approve'=>'approved','reject'=>'rejected','remove'=>'removed'];if(!isset($map[$action])){http_response_code(400);exit('Invalid action.');}$statement=$pdo->prepare('UPDATE events SET status=? WHERE event_id=?');$statement->execute([$map[$action],$id]);flash('Event status updated.');redirect('admin.php');
